Below is a complete, synthesisable implementation. Key architectural decisions (all forced by the contract):

* **Serial chain, no operand delay lines.** A3's `d(k) = D*(H-1-k)+3` is exactly the latency of a serial chain whose stages are 4 enabled ticks deep, with the last stage 3 deep. Stage `k` samples `x_i[r][k]`, `w_i[k]`, `rnd_i` (and stage 0 the bias / feedback) *directly* at its own sampling tick; the skew comes from the pipeline itself. The feedback is `z_o` through one extra register (`dfb = d(0)+1`).
* **Two combinational segments per FMA.** Flags are pinned by A10 to appear 2 enabled ticks after operand sampling, so the whole fused multiply-add (single rounding) is split as: seg1 = decode/specials/multiply/exact fixed-point placement/add → `B` register; seg2 = normalise/round/flags → `R1`+`F` registers; `R2` (and `R3` on interior stages) complete the 4-tick stage delay.
* **Exact wide accumulator.** The exact product (22 bits) and addend (11 bits) are placed in an 84-bit signed fixed-point grid with LSB weight 2⁻⁵⁰, so the sum is *exact by construction* — no sticky-capping corner cases; A5/A6/A7/A8 fall out of one rounding step at `max(e0, -14)`.
* **Flush** zeroes all inter-stage registers (including `z_o`'s) on the first gated edge; `status_o` updates normally on the first enabled tick of an assertion and holds thereafter (per-row `fs` tracks "flush at previous enabled tick"). Overflow follows the IEEE/hardware rule (rounded exponent > 15), which reproduces the A5 table exactly; underflow is tiny-before-rounding ∧ inexact.
* **slang/Verilator safe:** every declaration precedes every statement in each block; the only procedural loop is a 7-iteration binary MSB search (well under the 4000-iteration unroll budget); no variable part-selects; parameters carry defaults.

```systemverilog
// =============================================================================
// fp16_gemm_array -- d_ai01 implementation.
// WIDTH-row x HEIGHT-deep binary16 FMA array, per-stage delay D=4.
// =============================================================================
module fp16_gemm_array #(
  parameter int unsigned HEIGHT = 8,
  parameter int unsigned WIDTH  = 8
) (
  input  logic                                     clk_i,
  input  logic                                     rst_ni,
  input  logic [WIDTH-1:0][HEIGHT-1:0][15:0]       x_i,
  input  logic            [HEIGHT-1:0][15:0]       w_i,
  input  logic [WIDTH-1:0]            [15:0]       y_i,
  output logic [WIDTH-1:0]            [15:0]       z_o,
  input  logic [2:0]                               rnd_i,
  input  logic                                     accumulate_i,
  input  logic [WIDTH-1:0]                         row_clk_gate_en_i,
  input  logic                                     reg_enable_i,
  input  logic                                     flush_i,
  output logic [WIDTH-1:0][HEIGHT-1:0][4:0]        status_o
);

  // ---------------------------------------------------------------------------
  // MSB index of a nonzero 84-bit value (binary search, 7 constant iterations).
  // ---------------------------------------------------------------------------
  function automatic [6:0] msb_idx(input logic [83:0] v);
    logic [83:0] m;
    logic [6:0]  l;
    begin
      m = v;
      l = 7'd0;
      for (int kk = 6; kk >= 0; kk--) begin
        if ((m >> (7'd1 << kk)) != 84'd0) begin
          l = l + (7'd1 << kk);
          m = m >> (7'd1 << kk);
        end
      end
      msb_idx = l;
    end
  endfunction

  // ---------------------------------------------------------------------------
  // FMA segment 1: decode, special cases, exact product, fixed-point placement,
  // sign-magnitude add. Grid unit weight is 2^-50, so G is the EXACT |a*b+c|.
  // Packing: {G[83:0], sres, spq, scq, spec[1:0], isig}
  //   spec: 0 = normal, 1 = qNaN (no flag), 2 = qNaN + NV, 3 = infinity (isig)
  // ---------------------------------------------------------------------------
  function automatic [89:0] fma_s1(input logic [15:0] a,
                                  input logic [15:0] b,
                                  input logic [15:0] c);
    logic        sga, sgb, sgc;
    logic [4:0]  ea, eb, ec;
    logic [9:0]  ma, mb, mc;
    logic        anan, bnan, cnan, ainf, binf, cinf, azero, bzero;
    logic [10:0]       MA, MB, MC;
    logic signed [5:0] EA, EB, EC;
    logic [21:0]       MP;
    logic signed [6:0] EP;
    logic [6:0]        sp, scp;
    logic [83:0]       Pf, Cf, G;
    logic              ge, sres, spq, scq, isig;
    logic [1:0]        spec;
    begin
      sga = a[15]; ea = a[14:10]; ma = a[9:0];
      sgb = b[15]; eb = b[14:10]; mb = b[9:0];
      sgc = c[15]; ec = c[14:10]; mc = c[9:0];
      anan  = (ea == 5'h1F) && (ma != 10'd0);
      bnan  = (eb == 5'h1F) && (mb != 10'd0);
      cnan  = (ec == 5'h1F) && (mc != 10'd0);
      ainf  = (ea == 5'h1F) && (ma == 10'd0);
      binf  = (eb == 5'h1F) && (mb == 10'd0);
      cinf  = (ec == 5'h1F) && (mc == 10'd0);
      azero = (ea == 5'd0)   && (ma == 10'd0);
      bzero = (eb == 5'd0)   && (mb == 10'd0);
      spq   = sga ^ sgb;                 // sign of product
      scq   = sgc;                       // sign of addend
      spec  = 2'd0;
      isig  = 1'b0;
      G     = 84'd0;
      sres  = 1'b0;
      if (anan || bnan || cnan) begin
        spec = 2'd1;                     // any NaN -> canonical qNaN, no flag
      end else if ((ainf && bzero) || (azero && binf)) begin
        spec = 2'd2;                     // inf * zero -> qNaN + NV
      end else if (ainf || binf) begin
        isig = spq;
        if (cinf && (sgc != spq)) begin
          spec = 2'd2;                   // inf + (-inf) -> qNaN + NV
        end else begin
          spec = 2'd3;                   // correctly signed infinity, no flag
        end
      end else if (cinf) begin
        spec = 2'd3;
        isig = sgc;
      end else begin
        // significand*2^E with integer significand: value = M * 2^E
        MA = (ea == 5'd0) ? {1'b0, ma} : {1'b1, ma};
        MB = (eb == 5'd0) ? {1'b0, mb} : {1'b1, mb};
        MC = (ec == 5'd0) ? {1'b0, mc} : {1'b1, mc};
        EA = (ea == 5'd0) ? -6'sd24 : ($signed({1'b0, ea}) - 6'sd25);
        EB = (eb == 5'd0) ? -6'sd24 : ($signed({1'b0, eb}) - 6'sd25);
        EC = (ec == 5'd0) ? -6'sd24 : ($signed({1'b0, ec}) - 6'sd25);
        MP = MA * MB;                    // exact product, 22 bits
        EP = EA + EB;                    // [-48, 10]
        sp  = EP + 7'sd50;               // product field shift, [2, 60]
        scp = EC + 7'sd50;               // addend  field shift, [26, 55]
        Pf = {62'd0, MP} << sp;
        Cf = {73'd0, MC} << scp;
        if (spq == scq) begin
          G    = Pf + Cf;
          sres = spq;
        end else begin
          ge   = (Pf >= Cf);
          G    = ge ? (Pf - Cf) : (Cf - Pf);
          sres = ge ? spq : scq;
        end
      end
      fma_s1 = {G, sres, spq, scq, spec, isig};
    end
  endfunction

  // ---------------------------------------------------------------------------
  // FMA segment 2: normalise, single rounding, flags, encode.
  // value = G * 2^-50. Returns {result[15:0], flags[4:0]} with
  // flags packed {NV, DZ, OF, UF, NX}.
  // ---------------------------------------------------------------------------
  function automatic [20:0] fma_s2(input logic [83:0] G,
                                  input logic sres,
                                  input logic spq,
                                  input logic scq,
                                  input logic [1:0] spec,
                                  input logic isig,
                                  input logic [2:0] rnd);
    logic [83:0]       S, msk;
    logic [6:0]        l, sh;
    logic [10:0]       pre;
    logic              guard, roundb, sticky, inexact, inc;
    logic [11:0]       sig12;
    logic [10:0]       sig;
    logic signed [7:0] expr;
    logic [4:0]        fld;
    logic              zsign;
    logic [15:0]       res;
    logic [4:0]        fl;
    begin
      res = 16'h7E00;
      fl  = 5'd0;
      if (spec == 2'd1) begin
        res = 16'h7E00;
      end else if (spec == 2'd2) begin
        res = 16'h7E00;
        fl  = 5'b10000;                              // NV
      end else if (spec == 2'd3) begin
        res = {isig, 5'h1F, 10'd0};
      end else if (G == 84'd0) begin
        // exact zero: +0 unless both zeros share a negative sign; opposite
        // signs give +0 in every mode except RDN (-0). No flag (A8).
        zsign = (spq == scq) ? spq : (rnd == 3'd2);
        res   = {zsign, 15'd0};
      end else begin
        l  = msb_idx(G);
        // rounding position: normal results round at the MSB exponent,
        // tiny results at the fixed subnormal scale 2^-14.
        sh = (l >= 7'd36) ? (l - 7'd10) : 7'd26;
        S  = G >> (sh - 7'd2);
        pre    = S[12:2];
        guard  = S[1];
        roundb = S[0];
        msk    = {84{1'b1}} >> (7'd86 - sh);         // ones in [sh-3:0]
        sticky = (G & msk) != 84'd0;
        inexact = guard | roundb | sticky;
        case (rnd)
          3'd0: inc = guard && (roundb | sticky | pre[0]);   // RNE
          3'd1: inc = 1'b0;                                 // RTZ
          3'd2: inc = sres && inexact;                      // RDN
          3'd3: inc = (!sres) && inexact;                    // RUP
          3'd4: inc = guard;                                 // RMM
          default: inc = 1'b0;
        endcase
        sig12 = {1'b0, pre} + (inc ? 12'd1 : 12'd0);
        expr  = (l >= 7'd36) ? ($signed({1'b0, l}) - 8'sd50) : -8'sd14;
        if (sig12[11]) begin
          sig  = sig12[11:1];
          expr = expr + 8'sd1;
        end else begin
          sig = sig12[10:0];
        end
        if (expr > 8'sd15) begin
          // overflow: delivered value per A5, OF and NX raised
          fl = 5'b00101;
          case (rnd)
            3'd0, 3'd4: res = {sres, 5'h1F, 10'd0};          // +-inf
            3'd1:      res = {sres, 5'h1E, 10'h3FF};         // +-65504
            3'd2:      res = sres ? 16'hFC00 : 16'h7BFF;     // -inf / +65504
            3'd3:      res = sres ? 16'hFBFF : 16'h7C00;     // -65504 / +inf
            default:   res = {sres, 5'h1F, 10'd0};
          endcase
        end else begin
          // tiny (exact MSB below 2^-14) AND inexact -> UF (A6/A7)
          fl = {1'b0, 1'b0, 1'b0, ((l < 7'd36) && inexact), inexact};
          if ((expr == -8'sd14) && !sig[10]) begin
            res = {sres, 5'd0, sig[9:0]};                    // subnormal
          end else begin
            fld = expr + 8'sd15;
            res = {sres, fld, sig[9:0]};                    // normal
          end
        end
      end
      fma_s2 = {res, fl};
    end
  endfunction

  // ---------------------------------------------------------------------------
  // Rows and stages.
  // ---------------------------------------------------------------------------
  for (genvar gr = 0; gr < WIDTH; gr++) begin : g_row
    logic [HEIGHT-1:0][83:0] bt_a;      // seg1 results (B register bank)
    logic [HEIGHT-1:0]       bsres_a, bspq_a, bscq_a, bis_a;
    logic [HEIGHT-1:0][1:0]  bspec_a;
    logic [HEIGHT-1:0][2:0]  brnd_a;
    logic [HEIGHT-1:0][15:0] r1_a, r2_a, r3_a;
    logic [HEIGHT-1:0][4:0]  f_a;
    logic [15:0] fb_q;                  // accumulate feedback: z_o delayed 1
    logic       fs;                    // flush_i at this row's previous enabled tick
    logic [15:0] c0;

    assign c0     = accumulate_i ? fb_q : y_i[gr];
    assign z_o[gr] = r2_a[HEIGHT-1];

    // row-level state: feedback register and flush-assertion tracking
    always_ff @(posedge clk_i or negedge rst_ni) begin
      if (!rst_ni) begin
        fb_q <= 16'd0;
        fs   <= 1'b0;
      end else if (row_clk_gate_en_i[gr]) begin
        if (reg_enable_i) begin
          fs <= flush_i;
        end
        if (flush_i) begin
          fb_q <= 16'd0;                // flush outranks reg_enable (C2)
        end else if (reg_enable_i) begin
          fb_q <= r2_a[HEIGHT-1];
        end
      end
    end

    for (genvar gk = 0; gk < HEIGHT; gk++) begin : g_stg
      logic [15:0] cin;
      logic [89:0] s1;
      logic [20:0] s2;

      if (gk == 0) begin : g_c0
        assign cin = c0;
      end else begin : g_ck
        assign cin = r3_a[gk-1];         // previous stage's result, 4 ticks back
      end

      assign s1 = fma_s1(x_i[gr][gk], w_i[gk], cin);
      assign s2 = fma_s2(bt_a[gk], bsres_a[gk], bspq_a[gk], bscq_a[gk],
                         bspec_a[gk], bis_a[gk], brnd_a[gk]);
      assign status_o[gr][gk] = f_a[gk];

      always_ff @(posedge clk_i or negedge rst_ni) begin
        if (!rst_ni) begin
          bt_a[gk]    <= 84'd0;
          bsres_a[gk] <= 1'b0;
          bspq_a[gk]  <= 1'b0;
          bscq_a[gk]  <= 1'b0;
          bis_a[gk]   <= 1'b0;
          bspec_a[gk] <= 2'd0;
          brnd_a[gk]  <= 3'd0;
          r1_a[gk]    <= 16'd0;
          r2_a[g
